{"path": "/tmp/sv-e40793f1ddd640528cf9ca71f21ab17a/Components/Catalog/CatalogPagination.razor", "file_text": "@if (TotalPages > 1)
{
    <nav class="pagination" aria-label="Product pagination">
        <button class="page-btn"
                disabled="@(Page <= 1)"
                @onclick="@(() => GoToPage(Page - 1))">
            Previous
        </button>

        @foreach (var pageNum in GetPageNumbers())
        {
            <button class="page-btn @(pageNum == Page ? "active" : "")"
                    @onclick="@(() => GoToPage(pageNum))">
                @pageNum
            </button>
        }

        <button class="page-btn"
                disabled="@(Page >= TotalPages)"
                @onclick="@(() => GoToPage(Page + 1))">
            Next
        </button>
    </nav>
}

@code {
    [Parameter]
    public int Page { get; set; } = 1;

    [Parameter]
    public int TotalPages { get; set; }

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private async Task GoToPage(int page)
    {
        if (page >= 1 && page <= TotalPages && page != Page)
        {
            await OnPageChanged.InvokeAsync(page);
        }
    }

    private IEnumerable<int> GetPageNumbers()
    {
        const int maxVisible = 7;
        if (TotalPages <= maxVisible)
        {
            return Enumerable.Range(1, TotalPages);
        }

        var pages = new List<int>();
        int start = Math.Max(1, Page - maxVisible / 2);
        int end = Math.Min(TotalPages, start + maxVisible - 1);
        if (end - start < maxVisible - 1)
        {
            start = Math.Max(1, end - maxVisible + 1);
        }

        for (int i = start; i <= end; i++)
        {
            pages.Add(i);
        }
        return pages;
    }
}
"}

