toolArgs.file_text:
.catalog-sidebar {
    background: #fafafa;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem;
    height: 100%;
}

.catalog-sidebar h2 {
    margin: 0 0 1rem;
    font-size: 1.25rem;
    color: #333;
}

.filter-section {
    margin-bottom: 1.5rem;
}

.filter-section h3 {
    margin: 0 0 0.5rem;
    font-size: 0.9rem;
    font-weight: 600;
    color: #555;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.checkbox-label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.25rem 0;
    cursor: pointer;
    font-size: 0.9rem;
    color: #333;
}

.price-inputs {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.price-inputs input {
    width: 80px;
    padding: 0.4rem 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.9rem;
}

.price-inputs span {
    color: #999;
}

.filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.btn-apply {
    padding: 0.6rem 1rem;
    background: #0066cc;
    color: #fff;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-weight: 600;
    transition: background 0.2s;
}

.btn-apply:hover {
    background: #0052a3;
}

.btn-clear {
    padding: 0.6rem 1rem;
    background: transparent;
    color: #666;
    border: 1px solid #ccc;
    border-radius: 6px;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-clear:hover {
    background: #f0f0f0;
}

