.catalog-page {
    display: flex;
    min-height: calc(100vh - 3.5rem);
}

.catalog-page > :first-child {
    flex: 0 0 25%;
    max-width: 300px;
    min-width: 220px;
}

.catalog-main {
    flex: 1;
    padding: 1.5rem;
}

.loading-state,
.error-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 4rem 1rem;
    color: #666;
    font-size: 1.1rem;
}

.error-state {
    color: #c00;
}

.btn-retry {
    margin-top: 1rem;
    padding: 0.5rem 1.2rem;
    background: #0066cc;
    color: #fff;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-weight: 600;
}

.btn-retry:hover {
    background: #0052a3;
}

